<?php require 'db.php'; $method=$_SERVER['REQUEST_METHOD']; $data=json_decode(file_get_contents('php://input'),true) ?: [];
if($method==='GET'){ $q=$pdo->query('SELECT * FROM farmacias WHERE activo=1 ORDER BY nombre'); echo json_encode($q->fetchAll()); exit; }
if($method==='POST'){ if(empty($data['nombre'])||empty($data['direccion'])||!is_numeric($data['lat']??null)||!is_numeric($data['lng']??null)){http_response_code(400);echo json_encode(['message'=>'Nombre, dirección, latitud y longitud son obligatorios']);exit;} $st=$pdo->prepare('INSERT INTO farmacias(nombre,direccion,encargado,lat,lng) VALUES(?,?,?,?,?)');$st->execute([$data['nombre'],$data['direccion'],$data['encargado']??null,$data['lat'],$data['lng']]);echo json_encode(['success'=>true,'id'=>$pdo->lastInsertId()]);exit;}
if($method==='PUT'){ $st=$pdo->prepare('UPDATE farmacias SET nombre=?,direccion=?,encargado=?,lat=?,lng=? WHERE id_farmacia=?');$st->execute([$data['nombre'],$data['direccion'],$data['encargado']??null,$data['lat'],$data['lng'],$data['id_farmacia']]);echo json_encode(['success'=>true]);exit; }
if($method==='DELETE'){ $st=$pdo->prepare('UPDATE farmacias SET activo=0 WHERE id_farmacia=?');$st->execute([$_GET['id']]);echo json_encode(['success'=>true]); }
